import{_ as a,c as t,o as e,a3 as r}from"./chunks/framework.Dk6sf0Ip.js";const m=JSON.parse('{"title":"Nota Técnica: \\"Búsqueda Parcial\\" en Filtros de Reportes","description":"","frontmatter":{},"headers":[],"relativePath":"reportes/BusquedaParcial.md","filePath":"reportes/BusquedaParcial.md","lastUpdated":1759238350000}'),i={name:"reportes/BusquedaParcial.md"};function s(n,o,c,u,l,d){return e(),t("div",null,o[0]||(o[0]=[r('<h1 id="nota-tecnica-busqueda-parcial-en-filtros-de-reportes" tabindex="-1">Nota Técnica: &quot;Búsqueda Parcial&quot; en Filtros de Reportes <a class="header-anchor" href="#nota-tecnica-busqueda-parcial-en-filtros-de-reportes" aria-label="Permalink to &quot;Nota Técnica: &quot;Búsqueda Parcial&quot; en Filtros de Reportes&quot;">​</a></h1><h2 id="📌-definicion" tabindex="-1">📌 Definición <a class="header-anchor" href="#📌-definicion" aria-label="Permalink to &quot;📌 Definición&quot;">​</a></h2><p>El término <strong>(búsqueda parcial)</strong> indica que el sistema buscará coincidencias con <em>cualquier parte</em> del texto ingresado, sin requerir una coincidencia exacta.</p><h2 id="🔍-como-funciona" tabindex="-1">🔍 Cómo Funciona <a class="header-anchor" href="#🔍-como-funciona" aria-label="Permalink to &quot;🔍 Cómo Funciona&quot;">​</a></h2><ol><li><p><strong>No distingue mayúsculas/minúsculas</strong><br> Ejemplo: Buscar &quot;mate&quot; encontrará &quot;Material&quot;, &quot;MATERIALES&quot; y &quot;Herramientas-Mate&quot;</p></li><li><p><strong>Coincide con fragmentos</strong></p><ul><li><code>&quot;log&quot;</code> encontrará:<br> ✓ &quot;Logística S.A.&quot;<br> ✓ &quot;Analógica&quot;<br> ✓ &quot;Catalogo-2023&quot;</li></ul></li><li><p><strong>No necesita comodines</strong> (a diferencia de SQL)<br> El sistema automáticamente trata el texto como <code>%TEXTO%</code></p></li></ol><h2 id="💡-ejemplos-practicos" tabindex="-1">💡 Ejemplos Prácticos <a class="header-anchor" href="#💡-ejemplos-practicos" aria-label="Permalink to &quot;💡 Ejemplos Prácticos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Búsqueda</th><th>Encontrará</th></tr></thead><tbody><tr><td><code>&quot;2023&quot;</code></td><td>&quot;INS-2023&quot;, &quot;PED2023-001&quot;, &quot;2023-Materiales&quot;</td></tr><tr><td><code>&quot;cam&quot;</code></td><td>&quot;CAM-001&quot;, &quot;Cámara&quot;, &quot;Empaque-Camion&quot;</td></tr><tr><td><code>&quot;sa&quot;</code></td><td>&quot;S.A.&quot;, &quot;Mesas&quot;, &quot;Resaltado&quot;</td></tr></tbody></table><h2 id="⚠️-limitaciones" tabindex="-1">⚠️ Limitaciones <a class="header-anchor" href="#⚠️-limitaciones" aria-label="Permalink to &quot;⚠️ Limitaciones&quot;">​</a></h2><ul><li><strong>No soporta operadores avanzados</strong> (AND/OR)</li><li><strong>Sensibilidad a espacios</strong>:<br><code>&quot;log sa&quot;</code> ≠ <code>&quot;logsa&quot;</code></li><li><strong>Máximo rendimiento</strong> con 3+ caracteres</li></ul><h2 id="🛠-recomendaciones" tabindex="-1">🛠 Recomendaciones <a class="header-anchor" href="#🛠-recomendaciones" aria-label="Permalink to &quot;🛠 Recomendaciones&quot;">​</a></h2><ol><li><p>Para mayor precisión usar <strong>términos únicos</strong><br> Ej: <code>&quot;MAT-2023&quot;</code> en lugar de solo <code>&quot;2023&quot;</code></p></li><li><p>Combinar con otros filtros para <strong>reducir resultados</strong><br> (Fecha + Proveedor + Búsqueda parcial)</p></li><li><p><strong>Pruebas simples</strong> para verificar comportamiento<br> Ej: Buscar <code>&quot;a&quot;</code> mostrará todo lo que contenga esa letra</p></li></ol><p><em>🔍 El sistema indexa automáticamente los campos filtrables para optimizar estas búsquedas.</em></p>',12)]))}const p=a(i,[["render",s]]);export{m as __pageData,p as default};
